/** A sheet, identified by the id a user types to load it. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's "today": every date decision and default date in the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private long lastClaimNumber;

    /** The most due a clerk can settle a claim for; null for no limit. */
    @Column(name = "clerk_limit", precision = 14, scale = 2)
    private BigDecimal clerkLimit;

    /** The least any live due on the sheet can be; a settled claim's fixed due is kept as it was. */
    @Column(name = "floor", nullable = false, precision = 14, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** The sheet's terms: a claim is due by its date plus this many days. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    /** Each grade's own terms, by grade; a grade with none uses the sheet's terms. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_grade_terms", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "grade")
    @Column(name = "terms", nullable = false)
    private Map<String, Integer> gradeTerms = new HashMap<>();

    /** The sheet's late percent: an overdue claim's live due gains it, of its floored due, per full 30 days overdue. */
    @Column(name = "late_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal latePct = new BigDecimal("0.00");

    /** The sheet's policy date: it decides how a claim's live figures round; null for the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The sheet's period numbering from: from this date (by the sheet's today) claims opened are numbered within their period; null for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    /** The grade's own terms; null when it has none (it uses the sheet's terms). */
    public Integer getGradeTerms(String grade) {
        return gradeTerms.get(grade);
    }

    /** Set the grade's own terms; null removes them, so it uses the sheet's terms. */
    public void setGradeTerms(String grade, Integer days) {
        if (days == null) {
            gradeTerms.remove(grade);
        } else {
            gradeTerms.put(grade, days);
        }
    }

    /** The due-by of a claim of this date for a person of this grade now: its date plus the grade's terms, or the sheet's. */
    public LocalDate dueBy(String grade, LocalDate claimDate) {
        Integer own = gradeTerms.get(grade);
        return claimDate.plusDays(own != null ? own : terms);
    }

    public BigDecimal getLatePct() {
        return latePct;
    }

    public void setLatePct(BigDecimal latePct) {
        this.latePct = latePct;
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the period numbering from is set and today is on or after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /**
     * How a claim's live figures round: half up when it is dated before the policy date (the sheet's
     * today when none is set), half to even when dated on or after it.
     */
    public RoundingMode roundingFor(LocalDate claimDate) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return claimDate.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** An amount's due at a rate (a percent), rounded to cents as the claim's date decides. */
    public BigDecimal dueAt(BigDecimal amount, BigDecimal rate, LocalDate claimDate) {
        return amount.multiply(rate).divide(BigDecimal.valueOf(100), 2, roundingFor(claimDate));
    }

    /**
     * An open claim's live due (already floored; null stays null) with its late charge added: the late
     * percent of the floored due for every full 30 days its due-by (fixed when it was created) is before
     * today, rounded to cents as the claim's date decides.
     */
    public BigDecimal withLateCharge(BigDecimal floored, LocalDate claimDate, LocalDate dueBy) {
        if (floored == null) {
            return null;
        }
        long days = ChronoUnit.DAYS.between(dueBy, today);
        long periods = days > 0 ? days / 30 : 0;
        BigDecimal late = floored.multiply(latePct).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, roundingFor(claimDate));
        return floored.add(late);
    }

    /**
     * A claim's due at its rate (null for none) as it counts: a correction's as it is, with no floor
     * and no late charge; any other claim's floored, with its late charge added.
     */
    public BigDecimal liveDue(BigDecimal due, LocalDate claimDate, LocalDate dueBy, boolean correction) {
        return correction ? due : withLateCharge(floored(due), claimDate, dueBy);
    }

    /** A live due raised to the sheet's floor; null (no rate) stays null. */
    public BigDecimal floored(BigDecimal due) {
        return due == null ? null : due.max(floor);
    }

    /** Give out the sheet's next claim number. */
    public long takeClaimNumber() {
        return ++lastClaimNumber;
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.time.LocalDate;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads sheets by id; a sheet never loaded before is created empty. The real clock is read only
 * here, to start a new sheet's "today"; everything else uses {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Audit audit;
    private final Clock clock = Clock.systemDefaultZone();

    public SheetService(SheetRepository sheets, Audit audit) {
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> create(id, user));
    }

    /** The sheet's "today": the date every decision and default date in the sheet uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    }

    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        sheet.setToday(today);
        return sheet;
    }

    /**
     * Change the sheet's clerk limit (two decimals; null for no limit), floor (two decimals; null
     * leaves it as it is) terms (days; null leaves them as they are) and late percent (two
     * decimals; null leaves it as it is) and policy date (empty for none, the sheet's today; null
     * leaves it as it is) and period numbering from (empty for off; null leaves it as it is) and each
     * grade's own terms given (empty for none, the grade uses the sheet's terms). Each change is recorded as
     * SETTING_CHANGED key=&lt;key&gt; value=&lt;value&gt;, clerk-limit first, then floor, then terms, then
     * terms-&lt;grade&gt; by grade, then late-pct,
     * then policy-date, then period-numbering-from, the clerk limit's value empty for no limit and the policy date's and the period numbering from's
     * and a grade's terms' empty for none; setting a value it already has records nothing.
     */
    @Transactional
    public Sheet setSettings(String id, String user, BigDecimal limit, BigDecimal floor, Integer terms,
            BigDecimal latePct, Optional<LocalDate> policyDate, Optional<LocalDate> periodNumberingFrom,
            Map<String, Optional<Integer>> gradeTerms) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
        if (!Objects.equals(sheet.getClerkLimit(), scaled)) {
            sheet.setClerkLimit(scaled);
            audit.change("SETTING_CHANGED", id, user, "key=clerk-limit",
                    "value=" + (scaled == null ? "" : scaled.toPlainString()));
        }
        if (floor != null) {
            BigDecimal scaledFloor = floor.setScale(2, RoundingMode.UNNECESSARY);
            if (scaledFloor.compareTo(sheet.getFloor()) != 0) {
                sheet.setFloor(scaledFloor);
                audit.change("SETTING_CHANGED", id, user, "key=floor", "value=" + scaledFloor.toPlainString());
            }
        }
        if (terms != null && terms != sheet.getTerms()) {
            sheet.setTerms(terms);
            audit.change("SETTING_CHANGED", id, user, "key=terms", "value=" + terms);
        }
        gradeTerms.forEach((grade, days) -> {
            if (!Objects.equals(sheet.getGradeTerms(grade), days.orElse(null))) {
                sheet.setGradeTerms(grade, days.orElse(null));
                audit.change("SETTING_CHANGED", id, user, "key=terms-" + grade,
                        "value=" + days.map(String::valueOf).orElse(""));
            }
        });
        if (latePct != null) {
            BigDecimal scaledPct = latePct.setScale(2, RoundingMode.UNNECESSARY);
            if (scaledPct.compareTo(sheet.getLatePct()) != 0) {
                sheet.setLatePct(scaledPct);
                audit.change("SETTING_CHANGED", id, user, "key=late-pct", "value=" + scaledPct.toPlainString());
            }
        }
        if (policyDate != null && !Objects.equals(sheet.getPolicyDate(), policyDate.orElse(null))) {
            sheet.setPolicyDate(policyDate.orElse(null));
            audit.change("SETTING_CHANGED", id, user, "key=policy-date",
                    "value=" + policyDate.map(LocalDate::toString).orElse(""));
        }
        if (periodNumberingFrom != null
                && !Objects.equals(sheet.getPeriodNumberingFrom(), periodNumberingFrom.orElse(null))) {
            sheet.setPeriodNumberingFrom(periodNumberingFrom.orElse(null));
            audit.change("SETTING_CHANGED", id, user, "key=period-numbering-from",
                    "value=" + periodNumberingFrom.map(LocalDate::toString).orElse(""));
        }
        return sheet;
    }

    /**
     * The sheet, locked until the caller's transaction ends, so changes that must happen one at a
     * time on a sheet (such as giving out claim numbers) do; empty if the sheet was never loaded.
     */
    @Transactional
    public Optional<Sheet> lock(String id) {
        return sheets.findLockedById(id);
    }

    private Sheet create(String id, String user) {
        try {
            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock)));
        } catch (DataIntegrityViolationException e) {
            // Another user loaded the same new sheet at the same moment.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** Claims on a sheet. The signed-in user's name is sent in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * The amount is sent as text with exactly two decimals, so it is never rounded as a float; so is
     * the due fixed when the claim was settled (null if it is not settled or had no rate then).
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, String corrects,
            LocalDate dueBy, List<LogLineView> log) {
        static ClaimView of(Claim claim, List<ClaimStatusLog> log) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.getCorrects(), claim.getDueBy(),
                    log.stream().map(LogLineView::of).toList());
        }
    }

    /** A line of a claim's status log; the due as text with two decimals, null if it had no rate then. */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        static LogLineView of(ClaimStatusLog line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(),
                    line.getDue() == null ? null : line.getDue().toPlainString());
        }
    }

    /**
     * The amount has at most two decimals; a negative one is a correction, which names the number of
     * the settled claim it corrects. A missing date is the sheet's today.
     */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "-?\\d{1,10}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Size(max = 120) String corrects) {
    }

    /** The quick-add bar: a name (stored trimmed) and an amount, with the rules of the person and claim forms. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String amount) {
    }

    /** The claims selected to be opened together, by id. */
    public record BulkOpenRequest(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    private final ClaimService service;
    private final QuickAddService quickAdd;

    public ClaimController(ClaimService service, QuickAddService quickAdd) {
        this.service = service;
        this.quickAdd = quickAdd;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        Map<Long, List<ClaimStatusLog>> logs = service.logs(sheetId.trim());
        return service.list(sheetId.trim()).stream()
                .map(claim -> ClaimView.of(claim, logs.getOrDefault(claim.getId(), List.of())))
                .toList();
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ClaimRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), personId,
                new BigDecimal(request.amount()), request.date(), request.note(), blankAsNull(request.corrects())));
    }

    @PostMapping("/quick-add")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView quickAdd(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated QuickAddRequest request) {
        return view(quickAdd.add(sheetId.trim(), user.trim(), request.name(), new BigDecimal(request.amount())));
    }

    @PutMapping("/claims/{claimId}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ClaimRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), claimId,
                new BigDecimal(request.amount()), request.date(), request.note(), blankAsNull(request.corrects())));
    }

    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.VOID));
    }

    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.approve(sheetId.trim(), user.trim(), claimId));
    }

    /** The reason a steward rejects a PENDING claim for, stored trimmed. */
    public record RejectRequest(@NotBlank @Size(max = 200) String reason) {
    }

    @PostMapping("/claims/{claimId}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated RejectRequest request) {
        return view(service.reject(sheetId.trim(), user.trim(), claimId, request.reason().trim()));
    }

    /** The person on the sheet a steward moves a claim to, by id. */
    public record ReassignRequest(@NotNull Long personId) {
    }

    @PostMapping("/claims/{claimId}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ReassignRequest request) {
        return view(service.reassign(sheetId.trim(), user.trim(), claimId, request.personId()));
    }

    private ClaimView view(Claim claim) {
        return ClaimView.of(claim, service.log(claim));
    }

    /** A corrected number as sent, trimmed; none when blank. */
    private static String blankAsNull(String text) {
        return text == null || text.isBlank() ? null : text.trim();
    }

    @PostMapping("/claims/bulk-open")
    public ClaimService.BulkResult bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated BulkOpenRequest request) {
        return service.bulkOpen(sheetId.trim(), user.trim(), request.claimIds());
    }
}

