425	export function dueCents(cents: number, rate: string, halfUp = false): number {
426	  if (cents < 0) return -dueCents(-cents, rate, halfUp);
427	  const product = BigInt(cents) * BigInt(toCents(rate));
428	  const whole = product / 10000n;
